import { ArrowDownToLine, ArrowUpFromLine } from 'lucide-react'
import { useState } from 'react'
import { EmptyState, ErrorState, FormError, Loading, PageHeader } from '../components/ui'
import { api } from '../lib/api'
import { fmtDateTime, num, relative } from '../lib/format'
import { ALERTS_EVENT, useAsync } from '../lib/hooks'

// alerts are generated by the backend
export default function Alerts() {
  const [filter, setFilter] = useState<'all' | 'unread'>('all')
  const [actionError, setActionError] = useState<string | null>(null)
  const { data, error, loading, reload } = useAsync(() => api.alerts(), [])

  if (loading && !data) return <Loading />
  if (error || !data) return <ErrorState message={error ?? 'Could not load your alerts.'} onRetry={reload} />

  const unread = data.filter((a) => !a.readAt)
  const list = (filter === 'unread' ? unread : data).slice().sort((a, b) => b.createdAt.localeCompare(a.createdAt))

  async function markRead(ids: string[]) {
    setActionError(null)
    try {
      await Promise.all(ids.map((id) => api.markAlertRead(id)))
      window.dispatchEvent(new Event(ALERTS_EVENT))
      reload()
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Could not update the alerts.')
    }
  }

  return (
    <>
      <PageHeader
        title="Alerts"
        subtitle="Triggered when a watchlist card reaches your buy or sell target."
        actions={
          <button className="btn btn--ghost" disabled={!unread.length} onClick={() => markRead(unread.map((a) => a.id))}>
            Mark all as read
          </button>
        }
      />
      <FormError message={actionError} />

      <div className="tabs" role="tablist">
        <button role="tab" aria-selected={filter === 'all'} className={filter === 'all' ? 'is-active' : ''} onClick={() => setFilter('all')}>
          All ({data.length})
        </button>
        <button role="tab" aria-selected={filter === 'unread'} className={filter === 'unread' ? 'is-active' : ''} onClick={() => setFilter('unread')}>
          Unread ({unread.length})
        </button>
      </div>

      <div className="card">
        {!list.length ? (
          <EmptyState
            title={filter === 'unread' ? 'You are all caught up' : 'No alerts yet'}
            text="Set buy and sell targets on your watchlist and alerts will show up here."
          />
        ) : (
          <ul className="feed">
            {list.map((a) => (
              <li key={a.id} className={`feed__item${a.readAt ? '' : ' is-unread'}`}>
                <span className={`feed__icon feed__icon--${a.kind}`}>{a.kind === 'buy' ? <ArrowDownToLine size={18} /> : <ArrowUpFromLine size={18} />}</span>
                <div className="feed__body">
                  <strong>{a.kind === 'buy' ? 'Buy target reached' : 'Sell target reached'}</strong>
                  <span>
                    {a.cardName} hit <span className="mono strong">{num(a.triggeredPrice)}</span>
                  </span>
                  <span className="muted small" title={fmtDateTime(a.createdAt)}>
                    {relative(a.createdAt)}
                  </span>
                </div>
                {!a.readAt && (
                  <button className="btn btn--ghost btn--sm" onClick={() => markRead([a.id])}>
                    Mark as read
                  </button>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>
    </>
  )
}
